#' P-P Plot
#'
#' 
#' @param data .
#' @param x .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$ppp} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' @export
PPPlot <- function(
    data,
    x) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("PPPlot requires jmvcore to be installed (restart may be required)")

    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(x), x, NULL))


    options <- PPPlotOptions$new(
        x = x)

    analysis <- PPPlotClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

